#include "server1/local/LocalIndexer.h"
#include "server1/local/LocalFilename.h"
#include "server1/policy/TorrentMetadata.h"
#include <QFile>
#include <QFileInfo>
#include <QJsonArray>
#include <QPointer>
#include <QRegularExpression>
#include <QTimer>
#include <memory>
namespace server1::local {
namespace {
bool interesting(const QString &path){return QRegularExpression(".mkv$|.avi$|.mp4$|.wmv$|.vp8$|.mov$|.mpg$|.mp3$|.flac$",QRegularExpression::CaseInsensitiveOption).match(path).hasMatch();}
// Bound recursive downstream bdecode before handing bytes to the existing parser.
bool boundedBencode(const QByteArray &bytes){qsizetype i=0;int depth=0,nodes=0;while(i<bytes.size()){if(++nodes>100000)return false;char c=bytes[i++];if(c=='d'||c=='l'){if(++depth>64)return false;}else if(c=='e'){if(--depth<0)return false;if(depth==0)return true;}else if(c=='i'){auto end=bytes.indexOf('e',i);if(end<0)return false;i=end+1;if(depth==0)return true;}else if(c>='0'&&c<='9'){quint64 length=quint64(c-'0');while(i<bytes.size()&&bytes[i]>='0'&&bytes[i]<='9'){if(length>quint64(bytes.size()))return false;length=length*10+quint64(bytes[i++]-'0');}if(i>=bytes.size()||bytes[i++]!=':'||length>quint64(bytes.size()-i))return false;i+=qsizetype(length);if(depth==0)return true;}else return false;}return false;}
}
LocalIndexer::LocalIndexer(Config config,QObject *parent):QObject(parent),config_(std::move(config)),metadata_(config_.metadata,this),imdb_(config_.imdb,this){}
LocalIndexer::~LocalIndexer(){cancel();}
void LocalIndexer::cancel(){++generation_;queue_.clear();waiting_.clear();active_=0;metadata_.cancel();imdb_.cancel();}
QJsonObject LocalIndexer::decodeTorrent(QByteArray bytes,QString *error){if(bytes.size()>16*1024*1024||!boundedBencode(bytes)){if(error)*error="torrent exceeds structural limits or has malformed bencode";return {};}policy::ByteBuffer input(bytes.begin(),bytes.end());std::string message;auto torrent=policy::TorrentMetadata::parseForIndexing(input,&message);if(!torrent){if(error)*error=QString::fromStdString(message);return {};}QJsonArray files,announce;for(const auto &f:torrent->files())files.append(QJsonObject{{"path",QString::fromStdString(f.path)},{"name",QString::fromStdString(f.name)},{"length",qint64(f.length)},{"offset",qint64(f.offset)}});for(const auto &a:torrent->announce())announce.append(QString::fromStdString(a));return {{"infoHash",QString::fromStdString(torrent->infoHash())},{"name",QString::fromStdString(torrent->name())},{"files",files},{"announce",announce}};}
void LocalIndexer::recognize(QJsonObject query,Callback callback){auto name=LocalImdb::parseSearchTerm(query.value("name").toString());query["name"]=name;auto key=name+":"+query.value("year").toVariant().toString()+":"+query.value("type").toString();auto generation=generation_;if(cache_.contains(key)&&QDateTime::currentMSecsSinceEpoch()-cache_[key].when<43200000){auto result=cache_[key].result;QTimer::singleShot(0,this,[this,generation,result,callback]{if(generation==generation_)callback(result);});return;}const bool queued=waiting_.contains(key);waiting_[key].push_back(std::move(callback));if(queued)return;
    QPointer<LocalIndexer> owner(this);auto deliver=[owner,generation,key](QJsonObject result){if(!owner||owner->generation_!=generation)return;auto callbacks=owner->waiting_.take(key);for(auto &callback:callbacks){if(!owner||owner->generation_!=generation)return;callback(result);}};
    queue_.enqueue({query,deliver,key});pump();}
void LocalIndexer::pump(){while(active_<3&&!queue_.isEmpty()){auto task=queue_.dequeue();++active_;auto generation=generation_;QPointer<LocalIndexer> owner(this);auto finish=[owner,generation,task](QJsonObject result){if(!owner||generation!=owner->generation_)return;if(!result.value("id").toString().isEmpty())owner->cache_[task.key]={result,QDateTime::currentMSecsSinceEpoch()};--owner->active_;task.callback(result);if(owner&&generation==owner->generation_)owner->pump();};metadata_.recognize(task.query,[owner,generation,task,finish](QJsonObject result){if(!owner||generation!=owner->generation_)return;if(result.value("id").toString().isEmpty())owner->imdb_.recognize(task.query,finish);else finish(result);});}}
void LocalIndexer::processFile(QJsonObject file,Callback callback){auto parsed=parseLocalFilename(file.value("path").toString(),{{"strict",true},{"fromInside",true},{"fileLength",file.value("length")}});auto type=parsed.value("type").toString();if(type!="movie"&&type!="series"){auto generation=generation_;QTimer::singleShot(0,this,[this,generation,file,callback]{if(generation==generation_)callback(file);});return;}QJsonObject query{{"name",parsed.value("name")},{"type",parsed.value("type")}};if(parsed.contains("year"))query["year"]=parsed.value("year");recognize(query,[file,parsed,callback](QJsonObject result)mutable{if(!result.value("id").toString().isEmpty()){file["parsedName"]=parsed.value("name");file["type"]=parsed.value("type");file["imdb_id"]=result.value("id");if(parsed.value("season").toInt()){file["season"]=parsed.value("season");auto episode=parsed.value("episode").toArray();if(!episode.isEmpty())file["episode"]=episode.first();}}callback(file);});}
void LocalIndexer::indexFile(QString path,Callback callback){auto generation=generation_;if(QRegularExpression(".torrent$").match(path).hasMatch()){QFile file(path);if(!file.open(QIODevice::ReadOnly)||file.size()>config_.maxTorrentBytes){QTimer::singleShot(0,this,[this,generation,callback]{if(generation==generation_)callback({});});return;}auto torrent=decodeTorrent(file.readAll());if(torrent.isEmpty()){QTimer::singleShot(0,this,[this,generation,callback]{if(generation==generation_)callback({});});return;}indexParsedTorrent(torrent,std::move(callback));return;}
    QFileInfo info(path);if(!interesting(path)){QTimer::singleShot(0,this,[this,generation,callback]{if(generation==generation_)callback({{"files",QJsonArray{}}});});return;}
    if(!info.exists()){QTimer::singleShot(0,this,[this,generation,callback]{if(generation==generation_)callback({});});return;}
    processFile({{"path",path},{"name",info.fileName()},{"length",info.size()}},[info,callback](QJsonObject file){if(file.value("imdb_id").toString().isEmpty()){callback({{"files",QJsonArray{}}});return;}callback({{"dateModified",info.lastModified().toUTC().toString(Qt::ISODateWithMs)},{"itemId","local:"+file.value("imdb_id").toString()},{"name",file.value("name")},{"files",QJsonArray{file}}});});
}
void LocalIndexer::indexParsedTorrent(QJsonObject torrent,Callback callback){auto ih=torrent.value("infoHash").toString().toLower();auto files=torrent.value("files").toArray();auto selected=std::make_shared<QJsonArray>();for(int i=0;i<files.size();++i){auto f=files[i].toObject();f["idx"]=i;if(interesting(f["path"].toString()))selected->append(f);}auto remaining=std::make_shared<int>(selected->size());if(!*remaining){auto generation=generation_;QTimer::singleShot(0,this,[this,generation,callback]{if(generation==generation_)callback({{"files",QJsonArray{}}});});return;}QJsonValue sources=QJsonValue::Null;if(torrent.value("announce").isArray()){QJsonArray list{"dht:"+torrent.value("infoHash").toString()};for(auto a:torrent.value("announce").toArray())list.append("tracker:"+a.toString());sources=list;}QPointer<LocalIndexer> owner(this);auto generation=generation_;for(int i=0;i<selected->size();++i)processFile((*selected)[i].toObject(),[owner,generation,selected,remaining,i,ih,torrent,sources,callback](QJsonObject f){if(!owner||generation!=owner->generation_)return;(*selected)[i]=f;if(--*remaining==0)callback({{"itemId","bt:"+ih},{"ih",ih},{"name",torrent.value("name")},{"files",*selected},{"sources",sources}});});}
}
